func Registry() []ToolEntry {
	out := append([]ToolEntry(nil), documented...)
	out = append(out, completedRoutes()...)
	// Flow routes are alternate transports for these execute actions. Keep the
	// route spelling on the action record so exact lookup returns one operation
	// guide with a shared contract.
	routeAliases := map[string]string{
		"update_environment_feature":              "POST /api/features/{id}/update-environment",
		"deploy_integration":                      "POST /api/integrations/{id}/deploy",
		"record_runtime_observation":              "POST /api/operations/{id}/runtime",
		"assemble_environment":                    "POST /api/products/{id}/assemble-environment",
		"capture_candidate_dev_baseline":          "POST /api/products/{id}/candidate-dev/capture-baseline",
		"confirm_candidate_dev_restoration":       "POST /api/products/{id}/candidate-dev/confirm-restoration",
		"deploy_candidate_dev":                    "POST /api/products/{id}/candidate-dev/deploy",
		"release_candidate_dev":                   "POST /api/products/{id}/candidate-dev/release",
		"release_candidate_dev_after_restoration": "POST /api/products/{id}/candidate-dev/release-after-restoration",
		"request_candidate_dev_restoration":       "POST /api/products/{id}/candidate-dev/request-restoration",
		"reserve_candidate_dev":                   "POST /api/products/{id}/candidate-dev/reserve",
		"verify_candidate_dev_restoration":        "POST /api/products/{id}/candidate-dev/verify-restoration",
		"verify_candidate_dev_runtime":            "POST /api/products/{id}/candidate-dev/verify-runtime",
		"claim_composition_conflict":              "POST /api/products/{id}/conflicts/claim",
		"record_conflict_resolution":              "POST /api/products/{id}/conflicts/resolution",
		"verify_conflict_resolution":              "POST /api/products/{id}/conflicts/verify",
	}
	for i := range out {
		if out[i].Kind == "execute_action" {
			if route := routeAliases[out[i].Name]; route != "" {
				alias := "http_route:" + route
				if !contains(out[i].Aliases, alias) {
					out[i].Aliases = append(out[i].Aliases, alias)
				}
			}
		}
	}
	for i := range out {
		e := &out[i]
		if e.Kind != "execute_action" {
			continue
		}
		for j := range e.Inputs {
			f := &e.Inputs[j]
			f.Required = requiredScope[e.Name][f.Name] || requiredData[e.Name][f.Name] || f.Name == "action" || f.Name == "data"
			if t := fieldTypes[f.Name]; t != "" {
				f.Type = t
			}
		}
	}
	// These domain actions are also registered as named MCP wrappers. Their
	// wrapper uses the same action data schema with the scopes lifted to fields.
	for _, e := range documented {
		if e.Kind != "execute_action" || e.Area != "execution" {
			continue
		}
		mcpEntry := e
		mcpEntry.Kind = "mcp_tool"
		mcpEntry.Aliases = nil
		mcpEntry.Purpose = "Named MCP wrapper for the " + e.Name + " execution command. " + e.Purpose
		mcpEntry.Example = strings.Replace(e.Example, `"action":"`+e.Name+`",`, ``, 1)
		fields := mcpEntry.Inputs[:0]
		for _, f := range mcpEntry.Inputs {
			if f.Name != "action" {
				fields = append(fields, f)
			}
		}
		mcpEntry.Inputs = fields
		out = append(out, mcpEntry)
	}
	return out
}

